<script lang="ts">
	import { onMount } from "svelte";
	import { createDiagnosticSession, updateDiagnosticSession } from "@/lib/board-intelligence/diagnosis";
	import { parseBoardFile, parseKiCadPcb } from "@/lib/board-intelligence/parser";
	import type { BoardModel, Component, DiagnosticSession, DocumentSource, Measurement } from "@/lib/board-intelligence/types";

	const sample = "(kicad_pcb (version 20240108) (generator pcbnew)\n(general (thickness 1.6))\n(layers (0 \"F.Cu\" signal) (31 \"B.Cu\" signal))\n(net 0 \"\") (net 1 \"GND\") (net 2 \"VIN_19V\") (net 3 \"+3V3\")\n(footprint \"Package_SO:SOIC-8\" (layer \"F.Cu\") (at 65 45)\n(property \"Reference\" \"U17\") (property \"Value\" \"TPS62160\")\n(pad \"1\" smd rect (at -1.9 -1.9) (size 1 1) (layers \"F.Cu\") (net 2 \"VIN_19V\"))\n(pad \"2\" smd rect (at -1.9 1.9) (size 1 1) (layers \"F.Cu\") (net 1 \"GND\"))\n(pad \"3\" smd rect (at 1.9 1.9) (size 1 1) (layers \"F.Cu\") (net 3 \"+3V3\")))\n(footprint \"Capacitor_SMD:C_0603\" (layer \"F.Cu\") (at 48 38)\n(property \"Reference\" \"C43\") (property \"Value\" \"10uF\")\n(pad \"1\" smd rect (at -0.8 0) (size 1 1) (layers \"F.Cu\") (net 3 \"+3V3\"))\n(pad \"2\" smd rect (at 0.8 0) (size 1 1) (layers \"F.Cu\") (net 1 \"GND\")))\n(footprint \"TestPoint:TestPoint\" (layer \"B.Cu\") (at 82 58)\n(property \"Reference\" \"TP3\") (property \"Value\" \"3V3_TEST\")\n(pad \"1\" thru_hole circle (at 0 0) (size 2 2) (layers \"*.Cu\") (net 3 \"+3V3\")))";
	let board: BoardModel = parseKiCadPcb("framework-input-module.kicad_pcb", sample);
	let selectedRef = "U17";
	let query = "";
	let side: "top" | "bottom" = "top";
	let panel: "board" | "net" | "diagnosis" | "measurements" = "board";
	let photoUrl = "";
	let photoName = "";
	let aligning = false;
	let anchors = 0;
	let status = "Example board loaded · local-only";
	let session: DiagnosticSession = createDiagnosticSession(board, "插电不开机，充电灯不亮");
	let schematic: DocumentSource | undefined;
	let measurementKind: Measurement["kind"] = "voltage";
	let measurementValue = "";
	let measurementCondition: Measurement["condition"] = "unpowered";
	$: selected = board.components.find((item) => item.ref === selectedRef) ?? board.components[0];
	$: visible = board.components.filter((item) => item.side === side || item.side === "unknown").filter((item) => !query || (item.ref + " " + (item.value ?? "")).toLowerCase().includes(query.toLowerCase()));
	$: selectedNetIds = new Set(selected?.pins.map((pin) => pin.netId).filter((id): id is string => Boolean(id)) ?? []);
	$: selectedNets = board.nets.filter((net) => selectedNetIds.has(net.id));
	$: stats = { components: board.components.length, pads: board.components.reduce((sum, item) => sum + item.pads.length, 0), nets: board.nets.length };
	onMount(() => { const saved = localStorage.getItem("ee-board-lab-session"); if (saved) try { session = JSON.parse(saved) as DiagnosticSession; status = "Restored local diagnostic session"; } catch { /* ignored */ } });
	function select(item: Component) { selectedRef = item.ref; }
	function bx(x: number) { return 8 + (x / board.width) * 84; }
	function by(y: number) { return 8 + (y / board.height) * 84; }
	function netName(id?: string) { return board.nets.find((net) => net.id === id)?.name ?? "net unknown"; }
	async function importFiles(event: Event) {
		const input = event.currentTarget as HTMLInputElement;
		for (const file of Array.from(input.files ?? [])) {
			if (file.size > 20 * 1024 * 1024) { status = file.name + ": rejected over 20 MB"; continue; }
			const parsed = parseBoardFile(file.name, await file.text());
			if ("components" in parsed) { board = parsed; selectedRef = parsed.components[0]?.ref ?? ""; session = createDiagnosticSession(parsed, session.symptom); status = "Parsed " + file.name + ": " + parsed.components.length + " components, " + parsed.nets.length + " nets"; }
			else { schematic = parsed; board = { ...board, sources: [...board.sources, parsed] }; status = file.name + ": " + parsed.status + " · connectivity not asserted"; }
		}
		input.value = "";
	}
	function addPhoto(event: Event) { const file = (event.currentTarget as HTMLInputElement).files?.[0]; if (!file) return; if (file.size > 15 * 1024 * 1024) { status = "Photo rejected over 15 MB"; return; } photoName = file.name; photoUrl = URL.createObjectURL(file); aligning = true; anchors = 0; status = "Photo loaded · add three matching anchors"; }
	function addAnchor() { anchors += 1; if (anchors >= 3) { aligning = false; status = "Manual alignment saved · review overlay before trusting it"; } }
	function saveMeasurement() { if (!measurementValue.trim()) return; const item: Measurement = { id: "m-" + Date.now(), ref: selected?.ref, netId: selected?.pads[0]?.netId, kind: measurementKind, value: measurementValue.trim(), condition: measurementCondition, takenAt: new Date().toISOString(), verified: false }; session = updateDiagnosticSession(session, item); localStorage.setItem("ee-board-lab-session", JSON.stringify(session)); measurementValue = ""; status = "Measurement saved locally · unverified"; }
	function saveCaseDraft() { const key = "ee-board-lab-case-drafts"; const drafts = JSON.parse(localStorage.getItem(key) ?? "[]") as unknown[]; drafts.push({ id: "draft-" + Date.now(), boardId: board.boardId, symptom: session.symptom, measurements: session.measurements, hypotheses: session.hypotheses, status: "draft", evidenceQuality: "unverified", createdAt: new Date().toISOString() }); localStorage.setItem(key, JSON.stringify(drafts)); status = "Repair case draft saved locally · requires human confirmation"; }
	function exportSession() { const blob = new Blob([JSON.stringify({ board, session }, null, 2)], { type: "application/json" }); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = board.boardId + "-repair-session.json"; link.click(); URL.revokeObjectURL(url); }
</script>

<svelte:head><title>Board Intelligence &amp; AI Repair Lab</title><meta name="description" content="Private-by-default PCB parsing, board viewing, photo alignment and repair measurements." /></svelte:head>
<div class="lab-shell">
	<header class="lab-header"><div><a href="/tools/ee-intelligence/" class="back">← EE Intelligence</a><div class="eyebrow">BOARD INTELLIGENCE · AI REPAIR LAB</div><h1>Trace the real board.<br /><span>Measure before reasoning.</span></h1><p>本地优先的 PCB、照片、网络和维修测量工作台。解析器只报告它真正读到的连接。</p></div><div class="actions"><label class="button primary">Upload PCB / Schematic<input type="file" multiple accept=".kicad_pcb,.kicad_sch,.brd,.bdv,.bvr,.ipc,.pdf" on:change={importFiles} /></label><label class="button">Add board photo<input type="file" accept="image/png,image/jpeg,image/webp" on:change={addPhoto} /></label><button class="button" on:click={exportSession}>Export JSON</button></div></header>
	<div class="status"><i></i><strong>{status}</strong><span>PRIVATE WORKSPACE · browser local only</span></div>
	<section class="grid">
		<aside class="left">
			<div class="panel"><div class="panel-head">BOARD LIBRARY <span class="badge">LOCAL</span></div><div class="board-card"><b>PCB</b><span><strong>{board.model ?? "Framework Input Module"}</strong><small>{board.boardId}</small><small>{stats.components} components · {stats.nets} nets</small></span></div><div class="sources">{#each board.sources as source}<div><em>{source.status}</em><span><strong>{source.name}</strong><small>{source.format}</small></span></div>{/each}{#if schematic}<small class="warning">Schematic indexed as PARTIAL; no connectivity claim.</small>{/if}</div></div>
			<div class="panel"><div class="panel-head">COMPONENT SEARCH <span class="badge">{visible.length}</span></div><input class="search" bind:value={query} placeholder="U17, C43, value…" aria-label="Search components" /><div class="sides"><button class:active={side === "top"} on:click={() => (side = "top")}>TOP</button><button class:active={side === "bottom"} on:click={() => (side = "bottom")}>BOTTOM</button></div><div class="list">{#each visible as item}<button class:selected={selected?.ref === item.ref} on:click={() => select(item)}><b>{item.ref}</b><span><strong>{item.value ?? "value unknown"}</strong><small>{item.position.x.toFixed(1)} × {item.position.y.toFixed(1)} mm</small></span><em>{Math.round(item.sourceConfidence * 100)}%</em></button>{:else}<small>No components match.</small>{/each}</div></div>
		</aside>
		<main class="stage">
			<div class="tabs"><button class:active={panel === "board"} on:click={() => (panel = "board")}>Board View</button><button class:active={panel === "net"} on:click={() => (panel = "net")}>Net Explorer</button><button class:active={panel === "diagnosis"} on:click={() => (panel = "diagnosis")}>AI Repair</button><button class:active={panel === "measurements"} on:click={() => (panel = "measurements")}>Measurements</button></div>
			{#if panel === "board"}<div class="board-stage"><div class="board"><div class="silhouette"></div>{#each visible as item}<button class:selected={selected?.ref === item.ref} class="marker" style={"left:" + bx(item.position.x) + "%;top:" + by(item.position.y) + "%;"} on:click={() => select(item)}><i class:item-ic={item.ref.startsWith("U")} class:item-tp={item.ref.startsWith("TP")}></i><span>{item.ref}</span></button>{/each}{#if photoUrl}<img class="photo" src={photoUrl} alt={photoName} />{/if}</div>{#if photoUrl && aligning}<div class="align"><strong>Manual photo alignment</strong><span>{anchors}/3 anchors · choose matching points</span><button class="button primary" on:click={addAnchor}>Add matching anchor</button><small>Affine preview only; visual guesses stay uncertain.</small></div>{/if}<div class="legend"><span>Board {board.width} × {board.height} mm</span><span>{stats.components} components</span><span>{board.layersKnown ? "layer stack known" : "layer stack unknown"}</span></div></div>
			{:else if panel === "net"}<div class="explorer"><div class="eyebrow">CIRCUIT TOPOLOGY</div><h2>Net Explorer</h2><p>Same-Net membership is explicit; geometric adjacency and inner copper are not inferred.</p><div class="net-list">{#each board.nets as net}<button class:selected={selectedNetIds.has(net.id)} on:click={() => { selectedRef = net.members[0]?.ref ?? selectedRef; }}><b>{net.name || "(unnamed)"}</b><span>{net.members.length} member(s) · {net.relation}</span></button>{/each}</div>{#if selectedNets.length}<div class="selected-net"><h3>Selected component nets</h3>{#each selectedNets as net}<div><strong>{net.name}</strong><span>{net.members.map((member) => member.ref + "." + member.pinOrPad).join(" · ")}</span><small>Test points: {board.testPoints.filter((point) => point.netId === net.id).map((point) => point.label).join(", ") || "none recorded"}</small></div>{/each}</div>{/if}</div>
			{:else if panel === "diagnosis"}<div class="explorer"><div class="eyebrow">DETERMINISTIC REPAIR AGENT · OFFLINE SAFE</div><h2>Evidence-first diagnosis</h2><p>AI provider is optional. Suggestions use parsed nets plus recorded measurements and never invent a pin function or voltage.</p><label>Current symptom<textarea rows="3" value={session.symptom} on:input={(event) => (session = { ...session, symptom: (event.currentTarget as HTMLTextAreaElement).value })}></textarea></label><div class="hypotheses">{#each session.hypotheses as hypothesis}<article><strong>{hypothesis.title}</strong><em>{Math.round(hypothesis.confidence * 100)}%</em><p>{hypothesis.evidence.join(" · ")}</p><button on:click={() => (panel = "measurements")}>Record next measurement →</button></article>{/each}</div><div class="warning-box">⚠ Do not measure resistance on a powered board or short an unknown rail. Read test conditions before probing.</div></div>
			{:else}<div class="explorer"><div class="eyebrow">MEASUREMENT WORKSPACE</div><h2>Record an observation</h2><p>Every reading keeps its condition and stays local until exported.</p><div class="form"><label>Type<select bind:value={measurementKind}><option value="voltage">Voltage</option><option value="resistance">Resistance to ground</option><option value="continuity">Continuity</option><option value="diode">Diode mode</option><option value="scope">Oscilloscope</option></select></label><label>Value<input bind:value={measurementValue} placeholder="e.g. 3.28 V" /></label><label>Condition<select bind:value={measurementCondition}><option value="unpowered">Board unpowered</option><option value="powered">Board powered</option><option value="unknown">Condition unknown</option></select></label><button class="button primary" on:click={saveMeasurement} disabled={!measurementValue.trim()}>Save measurement</button></div><div class="measurements">{#each session.measurements as item}<div><b>{item.kind}</b><strong>{item.value}</strong><span>{item.condition}</span><small>{item.ref ?? "board"} · {item.verified ? "verified" : "unverified"}</small></div>{:else}<small>No measurements yet.</small>{/each}</div></div>{/if}
		</main>
		<aside class="right"><div class="panel"><div class="panel-head">SELECTED COMPONENT <span class="badge">{selected ? Math.round(selected.sourceConfidence * 100) + "%" : "—"}</span></div>{#if selected}<h2>{selected.ref}</h2><div class="value">{selected.value ?? "Value unknown"}<small>{selected.footprint}</small></div><div class="details"><span>Side<strong>{selected.side}</strong></span><span>Position<strong>{selected.position.x.toFixed(2)}, {selected.position.y.toFixed(2)} mm</strong></span><span>Pads<strong>{selected.pads.length}</strong></span></div><h3>Pins / pads</h3><div class="pins">{#each selected.pins as pin}<button on:click={() => { panel = "net"; query = netName(pin.netId); }}><b>{pin.number}</b><span>{netName(pin.netId)}</span></button>{/each}</div>{:else}<small>Select a component.</small>{/if}</div><div class="panel"><div class="panel-head">PHOTO / EVIDENCE <span class="badge">{photoUrl ? "LOADED" : "EMPTY"}</span></div>{#if photoUrl}<img class="preview" src={photoUrl} alt={photoName} /><small>{photoName} · {aligning ? "alignment pending" : "overlay ready"} · {anchors} anchors</small>{:else}<p>Add a real PCB photo for manual alignment and visual evidence.</p>{/if}</div><div class="panel"><div class="panel-head">CASE / PRIVACY <span class="badge">LOCAL</span></div><p>Uploads are parsed in the browser. Session data stays in localStorage and is never published to public assets. Draft cases remain unverified until a human confirms the root cause.</p><button class="button full" on:click={() => { localStorage.setItem("ee-board-lab-session", JSON.stringify(session)); status = "Session checkpoint saved"; }}>Save checkpoint</button><button class="button full" on:click={saveCaseDraft}>Save repair case draft</button><a class="case-link" href="/tools/ee-intelligence/">Review in Case Explorer ↗</a></div></aside>
	</section>
</div>

<style>
:global(body){background:var(--page-bg)}.lab-shell{width:min(1500px,calc(100% - 2rem));margin:auto;padding:1.2rem 0 3rem;color:var(--terminal-ink)}.lab-header{display:flex;justify-content:space-between;gap:2rem;padding:1rem 0 1.5rem}.back{color:var(--content-meta);font:700 .68rem ui-monospace,monospace;text-decoration:none}.eyebrow{color:var(--terminal-amber);font:700 .65rem ui-monospace,monospace;letter-spacing:.14em;text-transform:uppercase;margin-top:.7rem}h1{margin:.5rem 0 .7rem;font-size:clamp(2rem,5vw,4rem);line-height:.95;letter-spacing:-.06em}h1 span{color:var(--primary)}p{color:var(--content-meta);font-size:.78rem;line-height:1.55}.lab-header p{max-width:48rem}.actions{display:flex;gap:.4rem;align-items:flex-start;flex-wrap:wrap}.button{border:1px solid var(--terminal-line);background:var(--terminal-surface);color:var(--terminal-ink);border-radius:.2rem;padding:.6rem .75rem;font:700 .65rem ui-monospace,monospace;cursor:pointer}.button:hover,.button.primary{border-color:var(--primary);color:var(--primary)}.button input{display:none}.status{display:flex;gap:.6rem;align-items:center;border:1px solid var(--terminal-line);border-left:3px solid var(--primary);padding:.6rem .7rem;background:var(--terminal-surface-muted);font:700 .63rem ui-monospace,monospace}.status i{width:.45rem;height:.45rem;background:var(--primary);border-radius:50%}.status span{margin-left:auto;color:var(--content-meta)}.grid{display:grid;grid-template-columns:240px minmax(0,1fr) 280px;gap:.75rem;margin-top:.75rem;align-items:start}.left,.right{display:grid;gap:.75rem}.panel,.stage{border:1px solid var(--terminal-line);background:var(--terminal-surface);border-radius:.25rem}.panel{padding:.8rem}.panel-head{display:flex;justify-content:space-between;align-items:center;color:var(--content-meta);font:700 .6rem ui-monospace,monospace;letter-spacing:.1em}.badge{color:var(--primary);border:1px solid var(--primary);padding:.2rem .3rem;font-size:.55rem}.board-card{display:flex;gap:.55rem;padding:.7rem 0;border-bottom:1px solid var(--terminal-line)}.board-card>b{display:grid;place-items:center;width:38px;height:38px;border:1px solid var(--primary);color:var(--primary);font:800 .65rem ui-monospace,monospace}.board-card strong,.board-card small,.sources strong,.sources small,.list strong,.list small{display:block}.board-card strong{font-size:.72rem}.sources{display:grid;gap:.4rem;padding-top:.6rem}.sources>div{display:flex;gap:.45rem}.sources em{color:var(--primary);font:700 .5rem ui-monospace,monospace}.warning{color:var(--terminal-amber)}.search{width:100%;margin:.6rem 0 .35rem;box-sizing:border-box}.sides{display:flex;gap:.3rem}.sides button,.tabs button{border:1px solid var(--terminal-line);background:transparent;color:var(--content-meta);padding:.4rem .5rem;cursor:pointer;font:700 .58rem ui-monospace,monospace}.sides button.active,.tabs button.active{color:var(--primary);border-color:var(--primary)}.list{display:grid;gap:.2rem;margin-top:.5rem;max-height:400px;overflow:auto}.list button{display:grid;grid-template-columns:auto 1fr auto;gap:.4rem;text-align:left;border:1px solid transparent;background:transparent;color:inherit;padding:.45rem;cursor:pointer}.list button.selected,.list button:hover{border-color:var(--primary);background:color-mix(in srgb,var(--primary) 8%,transparent)}.list b{color:var(--primary);font:800 .68rem ui-monospace,monospace}.list em{color:var(--content-meta);font:700 .55rem ui-monospace,monospace}.stage{min-height:680px}.tabs{display:flex;gap:.3rem;flex-wrap:wrap;padding:.6rem;border-bottom:1px solid var(--terminal-line)}.board-stage{position:relative;min-height:620px;padding:1rem;overflow:hidden}.board{position:relative;width:min(780px,95%);aspect-ratio:1.25;margin:2rem auto}.silhouette{position:absolute;inset:4%;border-radius:4% 3% 8% 2%;background:linear-gradient(135deg,#18372f,#285345 50%,#18352e);border:1px solid #65b49c;box-shadow:0 0 0 7px color-mix(in srgb,#65b49c 10%,transparent),inset 0 0 40px #0a211b}.marker{position:absolute;transform:translate(-50%,-50%);z-index:2;border:0;background:transparent;color:#d4f3e6;cursor:pointer;text-shadow:0 1px 2px #000}.marker i{display:block;width:20px;height:13px;border:1px solid #e8c47b;background:#514d31}.marker i.item-ic{width:34px;height:20px;background:#171a1b;border-color:#ddd}.marker i.item-tp{width:15px;height:15px;border-radius:50%;background:#d09d31}.marker.selected i{box-shadow:0 0 0 3px var(--primary),0 0 18px color-mix(in srgb,var(--primary) 70%,transparent)}.marker span{display:block;font:700 .56rem ui-monospace,monospace}.photo{position:absolute;inset:4%;width:92%;height:92%;object-fit:cover;opacity:.35;mix-blend-mode:screen;pointer-events:none;border-radius:4%;z-index:1}.align{position:absolute;bottom:3.5rem;left:1rem;right:1rem;display:flex;gap:.5rem;align-items:center;flex-wrap:wrap;padding:.65rem;background:var(--terminal-surface);border:1px solid var(--terminal-amber);z-index:4}.align strong{color:var(--terminal-amber)}.align span,.align small{color:var(--content-meta)}.legend{position:absolute;bottom:1rem;left:1rem;right:1rem;display:flex;gap:.7rem;flex-wrap:wrap;color:var(--content-meta);font:700 .58rem ui-monospace,monospace}.explorer{padding:1.2rem;min-height:620px}.explorer h2{margin:.4rem 0}.net-list,.hypotheses,.measurements{display:grid;gap:.3rem;margin-top:1rem}.net-list button{display:flex;justify-content:space-between;gap:.5rem;text-align:left;border:1px solid var(--terminal-line);background:transparent;color:inherit;padding:.6rem;cursor:pointer}.net-list button.selected{border-color:var(--primary)}.net-list span{color:var(--content-meta);font-size:.62rem}.selected-net{margin-top:1rem;border-top:1px solid var(--terminal-line);padding-top:.8rem}.selected-net>div{display:grid;gap:.2rem;border:1px solid var(--terminal-line);padding:.6rem;margin-top:.35rem}.selected-net strong{color:var(--primary)}label{display:grid;gap:.3rem;color:var(--content-meta);font:700 .62rem ui-monospace,monospace;margin-top:1rem}textarea,input,select{border:1px solid var(--terminal-line);background:var(--terminal-surface-muted);color:var(--terminal-ink);padding:.5rem;font:inherit}.hypotheses article{border:1px solid var(--terminal-line);padding:.7rem}.hypotheses strong{display:inline-block;max-width:80%}.hypotheses em{float:right;color:var(--terminal-amber);font:700 .65rem ui-monospace,monospace}.hypotheses button{border:0;background:transparent;color:var(--primary);padding:0;cursor:pointer;font:700 .62rem ui-monospace,monospace}.warning-box{margin-top:1rem;border:1px solid var(--terminal-amber);padding:.7rem;color:var(--terminal-amber);font-size:.67rem;line-height:1.5}.form{display:grid;grid-template-columns:repeat(2,1fr);gap:.7rem}.form .button{align-self:end}.measurements>div{display:grid;grid-template-columns:auto auto auto 1fr;gap:.5rem;align-items:center;border-bottom:1px solid var(--terminal-line);padding:.6rem 0}.measurements b{color:var(--primary);font:700 .6rem ui-monospace,monospace}.measurements strong{color:var(--terminal-amber)}.right h2{margin:.6rem 0 .25rem;font:800 2rem ui-monospace,monospace}.value{color:var(--terminal-amber)}.value small{display:block;color:var(--content-meta)}.details{display:grid;grid-template-columns:repeat(2,1fr);gap:.5rem;margin:1rem 0}.details span{display:grid;gap:.2rem;color:var(--content-meta);font-size:.6rem}.details strong{color:var(--terminal-ink)}.pins{display:grid;gap:.2rem}.pins button{display:grid;grid-template-columns:auto 1fr;gap:.4rem;text-align:left;border:1px solid var(--terminal-line);background:transparent;color:inherit;padding:.4rem;cursor:pointer}.pins span{color:var(--primary);font-size:.65rem}.preview{width:100%;max-height:180px;object-fit:cover;margin-top:.6rem}.full{width:100%;margin-top:.5rem}.case-link{display:block;margin-top:.6rem;color:var(--primary);font:700 .62rem ui-monospace,monospace;text-decoration:none}@media(max-width:1100px){.grid{grid-template-columns:220px minmax(0,1fr)}.right{grid-column:1/-1;grid-template-columns:repeat(3,1fr)}}@media(max-width:720px){.lab-header{display:grid}.grid{display:flex;flex-direction:column}.left,.stage,.right{width:100%}.right{display:grid;grid-template-columns:1fr}.stage{min-height:0}.board-stage{min-height:450px}.form{grid-template-columns:1fr}.status span{display:none}}
</style>


